import { Request, Response, NextFunction } from "express";
import jwt from "jsonwebtoken";

const JWT_SECRET = process.env.JWT_SECRET || "securebank-jwt-secret-change-in-production";

export interface AuthPayload {
  userId: number;
  email: string;
  role: string;
}

export interface TwoFactorPayload {
  type: "2fa_pending";
  userId: number;
  email: string;
  role: string;
}

declare global {
  namespace Express {
    interface Request {
      user?: AuthPayload;
    }
  }
}

export function authenticate(req: Request, res: Response, next: NextFunction) {
  const authHeader = req.headers.authorization;
  const cookieToken = req.cookies?.token;

  const token = authHeader?.startsWith("Bearer ")
    ? authHeader.slice(7)
    : cookieToken;

  if (!token) {
    res.status(401).json({ error: "Authentication required" });
    return;
  }

  try {
    const payload = jwt.verify(token, JWT_SECRET) as AuthPayload;
    req.user = payload;
    next();
  } catch {
    res.status(401).json({ error: "Invalid or expired token" });
  }
}

export function requireAdmin(req: Request, res: Response, next: NextFunction) {
  if (!req.user || req.user.role !== "admin") {
    res.status(403).json({ error: "Admin access required" });
    return;
  }
  next();
}

function signPendingToken(payload: Omit<AuthPayload, "type">, type: "2fa_pending" | "login_passcode_pending"): string {
  return jwt.sign({ ...payload, type }, JWT_SECRET, { expiresIn: "5m" });
}

function verifyPendingToken(token: string, type: "2fa_pending" | "login_passcode_pending"): Omit<AuthPayload, "type"> | null {
  try {
    const p = jwt.verify(token, JWT_SECRET) as AuthPayload & { type: string };
    if (p.type !== type) return null;
    return { userId: p.userId, email: p.email, role: p.role };
  } catch {
    return null;
  }
}

export function signToken(payload: AuthPayload): string {
  return jwt.sign(payload, JWT_SECRET, { expiresIn: "7d" });
}

export function signTwoFactorToken(payload: Omit<TwoFactorPayload, "type">): string {
  return signPendingToken(payload, "2fa_pending");
}

export function signLoginPasscodeToken(payload: Omit<AuthPayload, "type">): string {
  return signPendingToken(payload, "login_passcode_pending");
}

export function verifyTwoFactorToken(token: string): (Omit<TwoFactorPayload, "type"> & { type: string }) | null {
  const payload = verifyPendingToken(token, "2fa_pending");
  if (!payload) return null;
  return { ...payload, type: "2fa_pending" };
}

export function verifyLoginPasscodeToken(token: string): Omit<AuthPayload, "type"> | null {
  return verifyPendingToken(token, "login_passcode_pending");
}
